CREATE TABLE public."StrategyBoard" (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, created_at timestamp with time zone DEFAULT now() NOT NULL, updated_at timestamp with time zone DEFAULT now() NOT NULL, event text NOT NULL, match_number smallint NOT NULL, scouted_by uuid DEFAULT auth.uid() NOT NULL, board jsonb DEFAULT '[]'::jsonb NOT NULL);
ALTER TABLE public."StrategyBoard" ENABLE ROW LEVEL SECURITY;
ALTER TABLE public."StrategyBoard" ADD CONSTRAINT "StrategyBoard_pkey" PRIMARY KEY (id);
ALTER TABLE public."StrategyBoard" ADD CONSTRAINT "StrategyBoard_scouted_by_fkey" FOREIGN KEY (scouted_by) REFERENCES public."User"(user_id);
GRANT ALL ON public."StrategyBoard" TO anon;
GRANT ALL ON public."StrategyBoard" TO authenticated;
GRANT ALL ON public."StrategyBoard" TO service_role;
CREATE POLICY "Enable insert for authenticated users only" ON public."StrategyBoard" FOR INSERT TO authenticated WITH CHECK ((scouted_by = auth.uid()));
CREATE POLICY "Enable read access for logged in users" ON public."StrategyBoard" FOR SELECT TO authenticated USING (true);
CREATE POLICY "Enable update for authenticated users only" ON public."StrategyBoard" FOR UPDATE TO authenticated USING (true);
CREATE POLICY "Enable delete for authenticated users only" ON public."StrategyBoard" FOR DELETE TO authenticated USING (true);
